//! Runtime pieces the code generated by `#[eval_fn]` uses: typed views of argument columns,
//! writers of result columns, and the [`Args`] accessors of `lazy` bodies.
#![doc(hidden)]
#![allow(non_upper_case_globals)]

use std::borrow::Cow;

use smallvec::SmallVec;
use zerocopy::FromBytes;
use zerocopy::little_endian::{F64, I64};

pub use tidb_base::Error;
use tidb_chunk::column::new_empty_column;
pub use tidb_chunk::{Column, Row};
use tidb_parser::types::{ETInt, ETReal, ETString, EvalType};
use tidb_types::etc::FieldType;

use super::{Args, BuiltinFunc};
use crate::context::EvalContext;
use crate::expression::{EvalState, Expr};

/// The argument columns of one call (most functions have at most 4 arguments).
pub type ArgCols<'a> = SmallVec<[&'a Column; 4]>;

/// A column with no type yet; the driver resets it for its result type.
pub fn empty_column() -> Column {
    new_empty_column(&FieldType::default())
}

/// Prepares a string result column for `n` rows.
#[inline]
pub fn reset_string(result: &mut Column, n: usize) {
    result.reserve_string(n);
}

/// The int64 values of an argument column.
pub struct IntView<'a>(&'a [I64]);

impl<'a> IntView<'a> {
    /// The view of `col`.
    #[inline(always)]
    pub fn new(col: &'a Column, n: usize) -> Self {
        IntView(&col.int64s()[..n])
    }
    /// Row `i`.
    #[inline(always)]
    pub fn get(&self, i: usize) -> i64 {
        self.0[i].get()
    }
}

/// The float64 values of an argument column.
pub struct RealView<'a>(&'a [F64]);

impl<'a> RealView<'a> {
    /// The view of `col`.
    #[inline(always)]
    pub fn new(col: &'a Column, n: usize) -> Self {
        RealView(&col.float64s()[..n])
    }
    /// Row `i`.
    #[inline(always)]
    pub fn get(&self, i: usize) -> f64 {
        self.0[i].get()
    }
}

/// The bytes of a string argument column.
pub struct BytesView<'a>(&'a Column);

impl<'a> BytesView<'a> {
    /// The view of `col`.
    #[inline(always)]
    pub fn new(col: &'a Column, _n: usize) -> Self {
        BytesView(col)
    }
    /// Row `i`.
    #[inline(always)]
    pub fn get(&self, i: usize) -> &'a [u8] {
        self.0.get_bytes(i)
    }
}

macro_rules! fixed_out {
    ($name:ident, $t:ty, $le:ty, $resize:ident) => {
        /// Writer of a fixed-length result column: `ResizeXxx(n, false)` and `MergeNulls(args...)`
        /// (Go's vector versions), then values and NULL flags row by row.
        pub struct $name<'a> {
            nulls: &'a mut [u8],
            data: &'a mut [$le],
        }

        impl<'a> $name<'a> {
            /// Resizes `result` to `n` rows, NULL where any of `args` is NULL.
            #[inline]
            pub fn new(result: &'a mut Column, n: usize, args: &[&Column]) -> Self {
                result.$resize(n, false);
                if !args.is_empty() {
                    result.merge_nulls(args);
                }
                let (nulls, data) = result.fixed_parts_mut();
                let data = <[$le]>::mut_from_bytes(data).expect("fixed-length column data");
                $name { nulls, data }
            }
            /// Whether row `i` is NULL.
            #[inline(always)]
            pub fn is_null(&self, i: usize) -> bool {
                self.nulls[i >> 3] & (1 << (i & 7)) == 0
            }
            /// Sets row `i` to `v`.
            #[inline(always)]
            pub fn set(&mut self, i: usize, v: $t) {
                self.data[i] = <$le>::new(v);
            }
            /// Sets row `i` to NULL.
            #[inline(always)]
            pub fn set_null(&mut self, i: usize) {
                self.nulls[i >> 3] &= !(1 << (i & 7));
            }

            /// `checked` loop: calls `f` for every row of `0..n` (NULL ones too: their
            /// values are garbage and their flags are masked), stores the values and
            /// returns whether any row that is not NULL is flagged. No early exit, so the
            /// compiler can vectorize the loop; 8 rows (one bitmap byte) at a time.
            #[inline(always)]
            pub fn run_checked<F>(&mut self, n: usize, f: F) -> bool
            where
                F: Fn(usize) -> ($t, bool),
            {
                let full = n / 8;
                let (head, tail) = self.data[..n].split_at_mut(full * 8);
                let mut bad = false;
                for ((blk, out8), byte) in head
                    .chunks_exact_mut(8)
                    .enumerate()
                    .zip(&self.nulls[..full])
                {
                    let base = blk * 8;
                    for j in 0..8 {
                        let (v, b) = f(base + j);
                        out8[j] = <$le>::new(v);
                        bad |= b & ((byte >> j) & 1 == 1);
                    }
                }
                for (j, o) in tail.iter_mut().enumerate() {
                    let i = full * 8 + j;
                    let (v, b) = f(i);
                    *o = <$le>::new(v);
                    bad |= b & (self.nulls[i >> 3] & (1 << (i & 7)) != 0);
                }
                bad
            }

            /// Calls `f` for every row of `0..n` that is not NULL and stores its result.
            /// Goes through the null bitmap a byte (8 rows) at a time; a byte without NULL
            /// runs the 8 rows without testing bits.
            #[inline(always)]
            pub fn run<F>(&mut self, n: usize, mut f: F) -> Result<(), Error>
            where
                F: FnMut(usize) -> Result<Option<$t>, Error>,
            {
                let data = &mut self.data[..n];
                let nulls = &mut self.nulls[..n.div_ceil(8)];
                for (b, nb) in nulls.iter_mut().enumerate() {
                    let base = b * 8;
                    let end = (base + 8).min(n);
                    let byte = *nb;
                    if byte == 0xFF {
                        for i in base..end {
                            match f(i)? {
                                Some(v) => data[i] = <$le>::new(v),
                                None => *nb &= !(1 << (i - base)),
                            }
                        }
                    } else if byte != 0 {
                        for i in base..end {
                            if byte & (1 << (i - base)) != 0 {
                                match f(i)? {
                                    Some(v) => data[i] = <$le>::new(v),
                                    None => *nb &= !(1 << (i - base)),
                                }
                            }
                        }
                    }
                }
                Ok(())
            }
        }
    };
}

fixed_out!(IntOut, i64, I64, resize_int64);
fixed_out!(RealOut, f64, F64, resize_float64);

/// [`Args`] of the row driver: evaluates `f.args[i]` on the row when asked.
pub struct RowArgs<'a> {
    f: &'a BuiltinFunc,
    st: &'a EvalState,
    row: Row<'a>,
}

impl<'a> RowArgs<'a> {
    /// The accessor for `row`.
    #[inline(always)]
    pub fn new(f: &'a BuiltinFunc, st: &'a EvalState, row: Row<'a>) -> Self {
        RowArgs { f, st, row }
    }
}

impl Args for RowArgs<'_> {
    #[inline(always)]
    fn len(&self) -> usize {
        self.f.args.len()
    }
    #[inline(always)]
    fn int(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<i64>, Error> {
        self.f.args[i].eval_int(ctx, self.st, self.row)
    }
    #[inline(always)]
    fn real(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<f64>, Error> {
        self.f.args[i].eval_real(ctx, self.st, self.row)
    }
    #[inline(always)]
    fn string(&mut self, ctx: &dyn EvalContext, i: usize) -> Result<Option<Cow<'_, [u8]>>, Error> {
        Ok(self.f.args[i]
            .eval_string(ctx, self.st, self.row)?
            .map(Cow::Owned))
    }
}

/// [`Args`] of the vector driver: reads row `i` of the evaluated argument columns.
pub struct VecArgs<'a> {
    cols: &'a [&'a Column],
    i: usize,
}

impl<'a> VecArgs<'a> {
    /// The accessor for row `i`.
    #[inline(always)]
    pub fn new(_f: &'a BuiltinFunc, cols: &'a [&'a Column], i: usize) -> Self {
        VecArgs { cols, i }
    }
}

impl Args for VecArgs<'_> {
    #[inline(always)]
    fn len(&self) -> usize {
        self.cols.len()
    }
    #[inline(always)]
    fn int(&mut self, _ctx: &dyn EvalContext, i: usize) -> Result<Option<i64>, Error> {
        let c = self.cols[i];
        Ok(if c.is_null(self.i) {
            None
        } else {
            Some(c.get_int64(self.i))
        })
    }
    #[inline(always)]
    fn real(&mut self, _ctx: &dyn EvalContext, i: usize) -> Result<Option<f64>, Error> {
        let c = self.cols[i];
        Ok(if c.is_null(self.i) {
            None
        } else {
            Some(c.get_float64(self.i))
        })
    }
    #[inline(always)]
    fn string(&mut self, _ctx: &dyn EvalContext, i: usize) -> Result<Option<Cow<'_, [u8]>>, Error> {
        let c = self.cols[i];
        Ok(if c.is_null(self.i) {
            None
        } else {
            Some(Cow::Borrowed(c.get_bytes(self.i)))
        })
    }
}

/// Go `genVecFromConstExpr`: evaluates the constant once and fills `n` rows.
pub fn fill_constant(
    ctx: &dyn EvalContext,
    st: &EvalState,
    expr: &Expr,
    as_type: EvalType,
    n: usize,
    col: &mut Column,
) -> Result<(), Error> {
    let row = Row::default();
    match as_type {
        ETInt => {
            let v = expr.eval_int(ctx, st, row)?;
            col.resize_int64(n, v.is_none());
            if let Some(v) = v {
                for x in col.int64s_mut() {
                    *x = I64::new(v);
                }
            }
        }
        ETReal => {
            let v = expr.eval_real(ctx, st, row)?;
            col.resize_float64(n, v.is_none());
            if let Some(v) = v {
                for x in col.float64s_mut() {
                    *x = F64::new(v);
                }
            }
        }
        ETString => {
            let v = expr.eval_string(ctx, st, row)?;
            col.reserve_string(n);
            for _ in 0..n {
                match &v {
                    Some(b) => col.append_bytes(b),
                    None => col.append_null(),
                }
            }
        }
        // D08.1 part 2: the other evaluation types come with the signatures that read them.
        other => {
            return Err(Error::plain(format!(
                "vector evaluation of a constant as {} is not ported yet",
                other.0
            )));
        }
    }
    Ok(())
}
